import hmac, hashlib, time

def sign(secret: bytes, payload: bytes, ts: int) -> str:
    msg = str(ts).encode() + b'.' + payload
    return hmac.new(secret, msg, hashlib.sha256).hexdigest()

def verify(secret, payload, ts, sig, skew=300):
    if abs(time.time() - ts) > skew:
        return False
    return hmac.compare_digest(sign(secret, payload, ts), sig)

